```javascript
function wordCount(text) {
  const counts = {};
  if (!text || typeof text !== 'string') {
    return counts;
  }

  // Convert to lowercase and match only sequences of a-z
  const words = text.toLowerCase().match(/[a-z]+/g);

  if (words) {
    for (const word of words) {
      counts[word] = (counts[word] || 0) + 1;
    }
  }

  return counts;
}
