```javascript
function romanToInt(s) {
  const romanMap = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
  };

  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const currentVal = romanMap[s[i]];
    const nextVal = romanMap[s[i + 1]];

    if (nextVal > currentVal) {
      total -= currentVal;
      // The loop continues to the next index, and the nextVal will be 
      // be added in the next iteration.
    } else {
      total += currentVal;
    }
  }
  return total;
}
