function fib(n) {
  if (n < 0) return null;
  if (n === 0) return 0n;
  if (n === 1) return 1n;

  let a = 0n;
  let b = 1n;

  for (let i = 2; i <= n; i++) {
    let temp = a + b;
    a = b;
    b = temp;
  }

  return b;
}
